// Bundled chapter content. src/data/*.json is generated by scripts/sync-content.ts from the web repo;
// never edit it by hand.
import dinh from '@/data/ky-nha-dinh.json';

export type ZhTok = { c: string; h?: string; v?: string; f?: 1; o?: 1; g?: number; m?: number };
export type Seg = { t: string; g?: number; m?: number; s?: 'ed' | 'on'; b?: 1 } | { fr: number } | { fo: string };
export type TextSeg = Extract<Seg, { t: string }>;
export type Passage = {
  id: string; year: string; reign: string; type: string; folio: string; pp: number;
  zh: ZhTok[] | null; vi: Seg[]; en: Seg[]; notes: Seg[][];
  plain: { vi: string; en: string; zh: string };
  par?: { t: string; d: string }[];
};
export type Year = { id: string; label: string; reign: string; title: string; sub?: string; enLabel?: string; enSub?: string; gz?: string; jul?: number };
export type Reign = { id: string; zh: string; vi: string; sub: string; en: string; enSub: string };
export type NavNode = { t: string; chapter?: string; anchor?: string; kids?: NavNode[] };
export type Entity = {
  id: string; type: string; names: { zh?: string; vi?: string };
  aliases?: { zh?: string[]; vi?: string[] };
  occurrences?: { zh: number; vi: number; total: number };
  review_required?: boolean; wikipedia_status?: string;
  variants?: { surface: string; lang: string; kind: string; status: string; evidence?: string }[];
  review?: { review_id: string; kind: string; reason: string }[];
  external?: { wikidata?: string; wikipedia?: { vi?: { title: string; url: string; extract?: string; retrieved_at?: string; revision?: number } } };
};
export type Relation = { relation_id: string; subject: string; predicate: string; object: string; evidence?: { zh?: string; vi?: string }; confidence?: number };
export type Mention = { e: string; en: string; l: 'zh' | 'vi'; tg: 'body' | 'note'; n?: number; t: string; c: [string, string]; rv?: 1 };
export type Chapter = {
  slug: string;
  work: { id: string; title: { zh: string; vi: string; en: string }; sections: { t: string; items: NavNode[] }[]; en?: Record<string, string> };
  title: { zh: string; vi: string; en: string };
  span: { from: number; to: number; years: number };
  sources: { zh: string; vi: string; en: string };
  reigns: Reign[]; years: Year[]; passages: Passage[];
  lexicon: { hanviet: Record<string, string>; glossary: Record<string, string>; variants: Record<string, string> };
  entities: Record<string, Entity>; relations: Relation[]; mentions: Mention[];
  enrichment: { status?: string };
};

const build = (c: Chapter) => {
  const occ: Record<string, number[]> = {}, out: Record<string, Relation[]> = {}, inn: Record<string, Relation[]> = {};
  c.mentions.forEach((m, i) => (occ[m.e] = occ[m.e] || []).push(i));
  c.relations.forEach((r) => { (out[r.subject] = out[r.subject] || []).push(r); (inn[r.object] = inn[r.object] || []).push(r); });
  return {
    ...c,
    YM: Object.fromEntries(c.years.map((y) => [y.id, y])) as Record<string, Year>,
    RM: Object.fromEntries(c.reigns.map((r) => [r.id, r])) as Record<string, Reign>,
    PI: Object.fromEntries(c.passages.map((p, i) => [p.id, i])) as Record<string, number>,
    occ, out, inn,
  };
};
export type Book = ReturnType<typeof build>;

export const CHAPTERS: Record<string, Book> = { 'ky-nha-dinh': build(dinh as unknown as Chapter) };
export const DEFAULT_CHAPTER = 'ky-nha-dinh';
export const WORK = CHAPTERS[DEFAULT_CHAPTER].work;
export const getChapter = (slug?: string) => CHAPTERS[slug || DEFAULT_CHAPTER] || CHAPTERS[DEFAULT_CHAPTER];

export const HAN = /[㐀-鿿豈-﫿\u{20000}-\u{2FFFF}]/u;
/** Accent-insensitive Vietnamese folding (same as the web reader). */
export const norm = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/đ/g, 'd');
export const entName = (e?: Entity) => (e ? e.names.vi || e.names.zh || e.id : '');
export const yearLabel = (y: Year, en = false) => `${en ? y.enLabel || y.label : y.title}${y.jul ? ' [' + y.jul + ']' : ''}`;
export const isText = (s: Seg): s is TextSeg => 't' in s;
